    /// <summary>The lock atlas cell of a number: rect (x0, y0, x1, y1) round the insert centre in design units (Unity y up), uv (u0, v0, u1, v1).</summary>
    public static void Cell(int shape, int number, out Vector4 rect, out Vector4 uv)
    {
        var hx = HX[shape]; var hy = HY[shape];
        rect = new Vector4(-hx, -hy, hx, hy);
        var col = number % 10; var row = number / 10;
        uv = new Vector4(col / 10f, 1f - (row + 1) / 10f, (col + 1) / 10f, 1f - row / 10f);
    }
    /// <summary>The panel (tag) atlas cell at a density: rect round the insert centre (units, y up), uv.</summary>
    public static void TagCell(int shape, int density, int number, out Vector4 rect, out Vector4 uv)
    {
        var t = TagOf(shape, density);
        rect = new Vector4(t[0], t[1], t[2], t[3]);
        var col = number % 10; var row = number / 10;
        uv = new Vector4(col / 10f, 1f - (row + 1) / 10f, (col + 1) / 10f, 1f - row / 10f);
    }
    /// <summary>The x (design units, round the insert centre) between the token's first character and the rest: the first shows left of it.</summary>
    public static float Split(int shape, int number)
    {
        var n = Mathf.Clamp(number, 0, 99);
        return shape == 1 ? SplitRound[n] : shape == 2 ? SplitLong[n] : SplitRect[n];
    }
